//! Targets: one app each, one module each (`src/targets/<name>/`).
//!
//! A target is a template, how `palette init` wires the app's config to the
//! generated file, how to reload the running app, and its `doctor` checks.
//! Adding an app means adding a folder and one line in `ALL`; no other target
//! changes.

mod alacritty;
mod bat;
mod borders;
mod btop;
mod fzf;
mod ghostty;
mod habit_tracker;
mod kitty;
mod lazygit;
mod neovim;
mod obsidian;
mod shell;
mod sketchybar;
mod sketchybar_item;
pub(crate) mod starship;
mod tmux;
mod vscodium;
mod wezterm;

use anyhow::Result;

use crate::paths::Paths;
use crate::system::{self, Outcome};
use crate::wiring::Wiring;

/// An app Palette can theme.
#[derive(Debug)]
pub struct Target {
    pub name: &'static str,
    /// The file this target writes into `~/.config/palette/current/`, if any.
    pub output: Option<Output>,
    pub wiring: Wiring,
    /// Is the app on this Mac? Only used for reports, never to decide what to write.
    pub installed: fn(&Paths) -> bool,
    /// Make the running app pick up the new file. Only called when wired.
    pub reload: fn(&Paths) -> Outcome,
    /// After `init --remove`: bring the running app back to the user's own
    /// config. Most apps just reload.
    pub unload: Option<fn(&Paths) -> Outcome>,
    /// Shell lines this target adds to `shell.sh` (environment variables that
    /// point a tool at its generated file). Generated by Palette, never by a theme.
    pub env: fn(&Paths) -> Vec<String>,
    /// Extra `palette doctor` findings, beyond wired / not wired.
    pub doctor: fn(&Paths) -> Vec<Note>,
}

#[derive(Debug)]
pub struct Output {
    /// File name inside `current/`.
    pub file: &'static str,
    /// minijinja template, see `docs/THEME_SPEC.md` for the variables.
    pub template: &'static str,
    /// May a theme folder replace `file` with its own copy? Never for files
    /// that can run programs (shell scripts, tmux/starship/fzf/lazygit
    /// configs, Lua): that would let a theme run code.
    pub overridable: bool,
    /// Post-process the rendered text (starship merges in the user's config).
    pub finish: Option<fn(&Paths, String) -> Result<String>>,
}

/// A `palette doctor` finding: `ok` false means something to fix.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Note {
    pub ok: bool,
    /// Informational: Palette dealt with it or it needs no action. Shown muted,
    /// never as a problem.
    pub info: bool,
    pub text: String,
}

impl Note {
    pub fn ok(text: impl Into<String>) -> Self {
        Self {
            ok: true,
            info: false,
            text: text.into(),
        }
    }
    /// A finding for information only (not a problem).
    pub fn info(text: impl Into<String>) -> Self {
        Self {
            ok: true,
            info: true,
            text: text.into(),
        }
    }
    pub fn fix(text: impl Into<String>) -> Self {
        Self {
            ok: false,
            info: false,
            text: text.into(),
        }
    }
}

/// Defaults for the optional parts; targets use `..BASE`.
pub const BASE: Target = Target {
    name: "",
    output: None,
    wiring: Wiring::Shell,
    installed: |_| false,
    reload: |_| Outcome::Skipped("nothing to reload".into()),
    unload: None,
    env: |_| Vec::new(),
    doctor: |_| Vec::new(),
};

pub const ALL: &[Target] = &[
    sketchybar::TARGET,
    sketchybar_item::TARGET,
    borders::TARGET,
    ghostty::TARGET,
    kitty::TARGET,
    alacritty::TARGET,
    tmux::TARGET,
    vscodium::TARGET,
    neovim::TARGET,
    obsidian::TARGET,
    btop::TARGET,
    shell::TARGET,
    starship::TARGET,
    fzf::TARGET,
    bat::TARGET,
    lazygit::TARGET,
    habit_tracker::TARGET,
    wezterm::TARGET,
];

/// The target named `name`.
pub fn get(name: &str) -> Option<&'static Target> {
    ALL.iter().find(|t| t.name == name)
}

/// Shared helper: a command-line tool on PATH or in Homebrew's folders.
pub fn has_program(name: &str) -> bool {
    system::find_program(name).is_some()
}

/// Shared helper: an app bundle in /Applications or ~/Applications.
pub fn has_app(paths: &Paths, bundle: &str) -> bool {
    std::path::Path::new("/Applications").join(bundle).is_dir()
        || paths.home().join("Applications").join(bundle).is_dir()
}
